export const CFOAI_SERVER_URL = 'https://api.cfo.ai/mcp';
export const CFOAI_FIX_COMMAND = 'Run `tally login cfoai` to connect cfo.ai.';

export interface CfoaiBudgetConfig {
  orgId?: string;
  scenario?: string;
  pageName?: string;
  table?: string;
  budgetRow?: string;
  spendRow?: string;
  remainingRow?: string;
  spendDetailTable?: string;
